const formData = reactive({
  id: null as string | null,
  title: '',
  description: '',
  difficulty: 3,
  due_date: '',
  tags: '',
  estimated_minutes: 60,
  quadrant: 'not_urgent_important'
})

// 两个问题自动分类状态
const isUrgent = ref<boolean | null>(null)
const isImportant = ref<boolean | null>(null)

// 设置紧急程度
function setUrgent(urgent: boolean) {
  isUrgent.value = urgent
  updateQuadrantFromQuestions()
}

// 设置重要程度
function setImportant(important: boolean) {
  isImportant.value = important
  updateQuadrantFromQuestions()
}

// 根据两个问题自动更新象限
function updateQuadrantFromQuestions() {
  if (isUrgent.value === null || isImportant.value === null) return

  const quadrantMap: Record<string, Record<string, number>> = {
    'true': { 'true': 1, 'false': 3 },      // 紧急：重要→Q1, 不重要→Q3
    'false': { 'true': 2, 'false': 4 }      // 不紧急：重要→Q2, 不重要→Q4
  }
  const quadrant = quadrantMap[String(isUrgent.value)][String(isImportant.value)]

  const quadrantStrings: Record<number, string> = {
    1: 'urgent_important',
    2: 'not_urgent_important',
    3: 'urgent_not_important',
    4: 'not_urgent_not_important'
  }

  selectedQuadrant.value = quadrant
  formData.quadrant = quadrantStrings[quadrant]
}

