import api from './client'
import type { UserCreate, UserLogin, UserResponse } from '@/types/user.types'
import type { Token } from '@/types/auth.types'

export const authApi = {
  async register(data: UserCreate): Promise<UserResponse> {
    const response = await api.post('/auth/register', data)
    return response.data
  },

  async login(data: UserLogin): Promise<Token> {
    const response = await api.post('/auth/login', data)
    return response.data
  },

  async getCurrentUser(): Promise<UserResponse> {
    const response = await api.get('/auth/me')
    return response.data
  },

  async updateMode(mode: 'game' | 'professional'): Promise<UserResponse> {
    const response = await api.put('/auth/mode', { mode })
    return response.data
  }
}

